import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.CZqXuAiL.js";const c=JSON.parse('{"title":"Blackhole (Per-IP Total Drop)","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/guide/blackhole.md","filePath":"openshield-xdp/guide/blackhole.md","lastUpdated":1786562213000}'),l={name:"openshield-xdp/guide/blackhole.md"};function n(h,s,o,r,p,k){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="blackhole-per-ip-total-drop" tabindex="-1">Blackhole (Per-IP Total Drop) <a class="header-anchor" href="#blackhole-per-ip-total-drop" aria-label="Permalink to &quot;Blackhole (Per-IP Total Drop)&quot;">​</a></h1><p>Blackholing an IP drops <strong>every</strong> packet destined to it, at the earliest possible point in the firewall — for as long as the blackhole is active. It is the &quot;take this tenant off the air&quot; switch for dedicated hosts: when one VPS IP is eating a flood big enough to endanger the whole box, you sacrifice that one address and everything else stays fast.</p><h2 id="the-one-exception-established-players-stay-online" tabindex="-1">The one exception: established players stay online <a class="header-anchor" href="#the-one-exception-established-players-stay-online" aria-label="Permalink to &quot;The one exception: established players stay online&quot;">​</a></h2><p>A blackhole is not a brick wall for people who were already playing. Sources with an <strong>established TCP connection</strong> to the blackholed IP — a real, completed handshake — keep passing. Crucially, they are exempt <em>from the blackhole only</em>: rate limits, suspicion scoring and bans still apply to them like anyone else.</p><p>When an established source goes quiet, a grace timer starts (default <strong>10 minutes</strong>). Reconnect within the window and you&#39;re straight back in — the timer resets. If the window lapses, the source loses its exemption and is dropped like everyone else until the blackhole ends. No new connections can be established while a blackhole is active — that&#39;s the point.</p><div class="warning custom-block"><p class="custom-block-title">UDP services</p><p>The established exemption needs a handshake to observe, and UDP has none (the firewall sees inbound packets only, so &quot;two-way UDP&quot; can&#39;t be proven). During a blackhole of a UDP-only service (Minecraft Bedrock, FiveM, voice), <strong>all</strong> UDP sources are dropped, players included. For TCP services (Minecraft Java, websites, APIs, SFTP) established players ride through.</p></div><h2 id="manual-blackhole" tabindex="-1">Manual blackhole <a class="header-anchor" href="#manual-blackhole" aria-label="Permalink to &quot;Manual blackhole&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blackhole</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 203.0.113.10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # until disabled</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blackhole</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 203.0.113.10</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --seconds</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # timed: 5 minutes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blackhole</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                           # active blackholes + remaining time</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blackhole</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 203.0.113.10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # lift one</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blackhole</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                          # lift all</span></span></code></pre></div><p>The TUI&#39;s <strong>IPs</strong> tab shows blackhole state per attached IP and lets you toggle it; the dashboard banner tells you whenever any blackhole is active, and blackhole drops get their own row in the Drop Paths panel. IPv6 works identically.</p><h2 id="auto-blackhole" tabindex="-1">Auto-blackhole <a class="header-anchor" href="#auto-blackhole" aria-label="Permalink to &quot;Auto-blackhole&quot;">​</a></h2><p>Off by default. When enabled, the firewall watches the inbound rate of each <strong>attached</strong> IP (see <a href="./attached-ips">Attached IPs</a> — the registry is what keeps auto-blackhole from ever touching an address you don&#39;t manage) and blackholes it when an attack crosses your magnitude:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">blackhole</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # master switch for the whole feature</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  auto_enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # opt-in: let the firewall blackhole on its own</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  auto_pps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">500000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # trigger: inbound packets/sec to one IP (0 = ignore)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  auto_bps</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # trigger: bytes/sec to one IP (0 = ignore)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  auto_sustain_sec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # rate must hold this long (anti-spike)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  auto_duration_sec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">300</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # blackhole lasts this long...</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  grace_minutes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # established-source grace window</span></span></code></pre></div><p>If the attack is still over the trigger when the timer expires, the blackhole extends for another <code>auto_duration_sec</code> — no flapping. Every automatic and manual blackhole/lift posts an alert (Discord/webhook) with the IP, the rate that caused it, and whether it was automatic.</p><h2 id="what-blackhole-is-not" tabindex="-1">What blackhole is <em>not</em> <a class="header-anchor" href="#what-blackhole-is-not" aria-label="Permalink to &quot;What blackhole is *not*&quot;">​</a></h2><ul><li>It does not replace per-source bans — those still handle the attackers themselves. Blackhole answers &quot;the target is more expensive to defend than to sacrifice.&quot;</li><li>It never touches your management access: the admin whitelist is evaluated <em>before</em> the blackhole, so whitelisted sources always get through.</li><li>Auto-blackhole requires the target to be an attached IP. If you see floods hitting addresses the registry doesn&#39;t know, attach them (or their subnet) first.</li></ul><h2 id="metrics" tabindex="-1">Metrics <a class="header-anchor" href="#metrics" aria-label="Permalink to &quot;Metrics&quot;">​</a></h2><p><code>/metrics</code> exposes active blackholes (per-IP: manual/auto, time remaining), cumulative blackhole-dropped packets, the live exemption count, and auto-blackhole event totals — see <a href="./../user-guide/metrics-api">Metrics &amp; API</a> for field names.</p>`,17)])])}const g=e(l,[["render",n]]);export{c as __pageData,g as default};
